/**
   * Scramble Logic - Modular Version
   * Target: Elements with [data-hover-scramble]
   */
function initScrambleButton() {
    const scrambleElements = document.querySelectorAll('[data-hover-scramble]');
    const chars = 'ABCDEFGHIJKLMNPQRSTUVWYZ0123456789#%*?@'; // Karakter acak

    scrambleElements.forEach((el) => {
      // Cari span di dalamnya atau gunakan element itu sendiri
      const textTarget = el.querySelector('.btn-text') || el;
      const originalText = textTarget.innerText;
      const duration = parseFloat(el.dataset.duration) || 1;

      let scrambleTimeline;

      el.addEventListener('mouseenter', () => {
        let iteration = 0;

        // Kill animation sebelumnya jika masih jalan
        if (scrambleTimeline) clearInterval(scrambleTimeline);

        scrambleTimeline = setInterval(() => {
          textTarget.innerText = originalText
            .split('')
            .map((char, index) => {
              // Lewati spasi
              if (originalText[index] === ' ') return ' ';

              if (index < iteration) {
                return originalText[index];
              }
              return chars[Math.floor(Math.random() * chars.length)];
            })
            .join('');

          if (iteration >= originalText.length) {
            clearInterval(scrambleTimeline);
            textTarget.innerText = originalText; // Pastikan teks kembali sempurna
          }

          // Kecepatan berdasarkan durasi (60fps baseline)
          iteration += originalText.length / (duration * 40);
        }, 30);
      });

      // Reset instan saat mouse leave
      el.addEventListener('mouseleave', () => {
        clearInterval(scrambleTimeline);
        textTarget.innerText = originalText;
      });
    });
  }

  window.addEventListener('DOMContentLoaded', initScrambleButton);